package com.alpharip.staffmod.cases.evidencecaselinker; import net.minecraft.client.gui.*;import java.io.IOException;import java.util.*; public final class EvidenceCaseLinkerGui extends GuiScreen {private final GuiScreen parent;private final EvidenceCaseLinker module;private GuiTextField ref,id,note,search;private String notice="";public EvidenceCaseLinkerGui(GuiScreen p,EvidenceCaseLinker m){parent=p;module=m;}public void initGui(){buttonList.clear();int x=Math.max(8,width/2-205);ref=new GuiTextField(1,fontRendererObj,x,48,400,18);id=new GuiTextField(2,fontRendererObj,x,91,150,18);note=new GuiTextField(3,fontRendererObj,x+155,91,245,18);search=new GuiTextField(4,fontRendererObj,x,135,300,18);for(GuiTextField f:fields())f.setMaxStringLength(180);buttonList.add(new GuiButton(1,x+305,134,95,20,"Filter"));buttonList.add(new GuiButton(2,x,height-28,90,20,"Link"));buttonList.add(new GuiButton(3,x+95,height-28,90,20,"Save"));buttonList.add(new GuiButton(4,x+190,height-28,90,20,"Close"));buttonList.add(new GuiButton(5,x+285,height-28,115,20,"Remove first match"));}private List<GuiTextField> fields(){return Arrays.asList(ref,id,note,search);}protected void actionPerformed(GuiButton b)throws IOException{if(b.id==4){mc.displayGuiScreen(parent);return;}if(b.id==2){try{module.getService().link(new EvidenceLink(ref.getText(),id.getText(),note.getText(),System.currentTimeMillis()));notice="Evidence linked locally.";}catch(Exception e){notice="Enter an evidence reference and case ID.";}}if(b.id==3)notice=module.save()?"Saved locally.":"Save failed.";if(b.id==5){List<EvidenceLink> f=module.getService().findByReference(search.getText());notice=!f.isEmpty()&&module.getService().unlink(f.get(0).getEvidenceReference())?"First match removed; save to persist.":"No matching reference.";}}protected void keyTyped(char c,int k)throws IOException{for(GuiTextField f:fields())f.textboxKeyTyped(c,k);super.keyTyped(c,k);}protected void mouseClicked(int x,int y,int b)throws IOException{super.mouseClicked(x,y,b);for(GuiTextField f:fields())f.mouseClicked(x,y,b);}public void updateScreen(){for(GuiTextField f:fields())f.updateCursorCounter();}public void drawScreen(int mx,int my,float pt){drawDefaultBackground();int x=Math.max(8,width/2-205);drawCenteredString(fontRendererObj,"EVIDENCE CASE LINKER",width/2,18,0xFFFFC83D);drawString(fontRendererObj,"Evidence reference",x,35,0xFFFFFF);drawRect(x,48,x+401,67,0xAA20242C);ref.drawTextBox();drawString(fontRendererObj,"Case ID / note",x,78,0xFFFFFF);drawRect(x,91,x+151,110,0xAA20242C);drawRect(x+155,91,x+401,110,0xAA20242C);id.drawTextBox();note.drawTextBox();drawString(fontRendererObj,"Filter by reference",x,122,0xFFFFFF);drawRect(x,135,x+301,154,0xAA20242C);search.drawTextBox();int y=170;for(EvidenceLink e:module.getService().findByReference(search.getText())){drawString(fontRendererObj,fontRendererObj.trimStringToWidth(e.getEvidenceReference()+" -> "+e.getCaseId()+" | "+e.getNote(),width-2*x),x,y,0xFFE5E7EB);y+=14;if(y>height-48)break;}if(!notice.isEmpty())drawCenteredString(fontRendererObj,notice,width/2,height-43,0xFFFFC83D);super.drawScreen(mx,my,pt);}public boolean doesGuiPauseGame(){return false;}}